import { Injectable, signal } from '@angular/core';

/**
 * Interface que define a estrutura de um Imóvel
 */
export interface Property {
  id: number;
  title: string;
  subtitle: string;
  description: string;
  idealization?: Construtora,
  location: endereco;
  state: string;
  price: number;
  price_promo: number;
  towers: number;
  units_available: number;
  date?: Date;
  specs: {
    bedrooms: number,
    bathrooms: number,
    suits: number,
    balcony: boolean,
    area: number[],
    garden: boolean,
    parking: number,
    pool?: boolean,
    elevator: number
  },
  features: string[],
  amenities: string[],
  type: 'Estudio' | 'Apartamento' | 'Suites' | 'Casa' | 'Cobertura' | 'Duplex' | 'Triplex' | 'Loja' | 'Sala' | 'Galpão' | 'Terreno';
  status: 'Pronto' | 'Lançamento' | 'Em obras' | '100% Vendido' | 'Em Breve';
  category: string[];
  imagesUrl: Implantacao[];
  planta: Planta[];
  isPromo?: boolean;
  favorite: boolean;
  bookUrl?: string;
}

export interface Implantacao {
  [x: string]: any;
  id: number;
  description: string;
  imagesUrl: string;
}

export interface Planta {
  id: number;
  description: string;
  location: {
    towers: any[],
    floor: number[]
  };
  price: number;
  price_promo: number;
  specs: {
    bedrooms: number,
    bathrooms?: number,
    suits?: number,
    balcony?: boolean,
    area: number[],
    garden?: boolean,
    parking?: number
  },
  features: string[],
  status: 'Disponível' | 'Espelho' | 'Reservada' | 'Vendida' | 'Bloqueada',
  imagesUrl: string,
  category: 'HIS-1' | 'HIS-2' | 'R2V' | 'HMP' | 'NR'
}

export interface Construtora {
  id: number;
  imagesUrl: string;
  title: string;
  cnpj: string;
  description: string;
  location: string;
  date?: Date;
  site: string;
}

export interface Logo {
  id: number;
  imagesUrl: string;
  description: string;
}

export interface endereco {
  id: number;
  rua: string;
  numero: number;
  bairro: string;
  cidade: string;
  estado: string;
  cep: string;
  regiao: 'Zona Oeste' | 'Zona Norte' | 'Zona Leste' | 'Zona Sul' | 'Centro';
}

export interface MensagemPadrao {
  id: number;
  titulo: string;
  mensagem: string;
}

export interface MenuItem {
  path: string;
  label: string;
  description: string;
  icon: string;
  enable: boolean;
}

/**
 * Interface para as definições globais do site
 */
export interface AppSettings {
  siteTitle: string;
  logo: Logo[];
  backgroundImageUrl: string;
  whatsappConfig: {
    whatsappContactName: string;
    whatsappNumber: string,
    whatsappMessage: string
  };
  desenvolvedora: {
    id: number;
    nome: string;
    contato: {
      nome: string,
      telefone: string
    }
  };
  exibirValor: boolean;
}


